class Solution {
public:
    std::vector<int> smallestTrimmedNumbers(std::vector<std::string>& nums, std::vector<std::vector<int>>& queries) {
        std::vector<int> ans;
        int n = nums.size(), L = nums[0].size();
        for (const auto& q : queries) {
            int k = q[0], trim = q[1];
            std::vector<std::pair<std::string, int>> trimmed(n);
            for (int i = 0; i < n; ++i) {
                trimmed[i] = {nums[i].substr(L - trim), i};
            }
            std::sort(trimmed.begin(), trimmed.end());
            ans.push_back(trimmed[k - 1].second);
        }
        return ans;
    }
};

class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int qCount = queries.length;
        int[] ans = new int[qCount];
        int n = nums.length, L = nums[0].length();
        for (int q = 0; q < qCount; ++q) {
            int k = queries[q][0], trim = queries[q][1];
            Integer[] idx = new Integer[n];
            for (int i = 0; i < n; ++i) idx[i] = i;
            int start = L - trim;
            java.util.Arrays.sort(idx, (a, b) -> {
                String sa = nums[a].substring(start);
                String sb = nums[b].substring(start);
                int cmp = sa.compareTo(sb);
                return cmp != 0 ? cmp : Integer.compare(a, b);
            });
            ans[q] = idx[k - 1];
        }
        return ans;
    }
}

var smallestTrimmedNumbers = function(nums, queries) {
    const ans = [];
    const L = nums[0].length;
    for (const [k, trim] of queries) {
        const start = L - trim;
        const trimmed = nums.map((num, i) => [num.slice(start), i]);
        trimmed.sort((a, b) => {
            if (a[0] < b[0]) return -1;
            if (a[0] > b[0]) return 1;
            return a[1] - b[1];
        });
        ans.push(trimmed[k - 1][1]);
    }
    return ans;
};
